    "code": "<style>\n.od{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:12px}\n@media (max-width:560px){.od{grid-template-columns:1fr}}\n.kv{display:grid;grid-template-columns:auto 1fr;gap:4px 12px}\n.kv dt{color:var(--color-text-secondary)}\n.kv dd{margin:0;text-align:right}\n.tl{list-style:none;margin:0;padding:0}\n.tl li{display:flex;gap:8px;align-items:baseline;padding:4px 0}\n</style>\n<canopy-markup>\n<div class=\"stack\" style=\"gap:12px;padding:4px\">\n  <div class=\"row\" style=\"justify-content:space-between;flex-wrap:wrap\">\n    <div class=\"stack\" style=\"gap:2px\">\n      <small class=\"faint\">Orders / o-1</small>\n      <div class=\"row\"><h3 style=\"margin:0\">Order o-1</h3><span class=\"dot warn\"></span><span class=\"muted\">Awaiting fulfillment</span></div>\n      <small class=\"muted\">Placed Nov 18, 2026 at 2:14 PM</small>\n    </div>\n    <div class=\"row\">\n      <button>Refund</button>\n      <button>Cancel order</button>\n      <button class=\"primary\">Mark as shipped</button>\n    </div>\n  </div>\n\n  <div class=\"od\">\n    <div class=\"stack\" style=\"gap:12px\">\n      <div class=\"card stack\">\n        <div class=\"row\" style=\"justify-content:space-between\"><b style=\"font-weight:500\">Items</b><small class=\"muted\">1 line</small></div>\n        <table>\n          <thead><tr><th>Item</th><th class=\"num\">Price</th><th class=\"num\">Qty</th><th class=\"num\">Total</th></tr></thead>\n          <tbody><tr><td>Item 1</td><td class=\"num\">$12.50</td><td class=\"num\">2</td><td class=\"num\">$25.00</td></tr></tbody>\n        </table>\n        <dl class=\"kv\" style=\"margin:0\">\n          <dt>Subtotal</dt><dd>$25.00</dd>\n          <dt>Shipping</dt><dd>$0.00</dd>\n          <dt style=\"color:var(--color-text-primary)\">Total</dt><dd style=\"font-weight:500\">$25.00</dd>\n        </dl>\n      </div>\n      <div class=\"card stack\">\n        <b style=\"font-weight:500\">Activity</b>\n        <ul class=\"tl\">\n          <li><span class=\"dot\"></span><span>Order placed</span><small class=\"faint\" style=\"margin-left:auto\">Nov 18, 2:14 PM</small></li>\n          <li><span class=\"dot good\"></span><span>Payment captured</span><small class=\"faint\" style=\"margin-left:auto\">Nov 18, 2:14 PM</small></li>\n        </ul>\n        <textarea rows=\"2\" placeholder=\"Add an internal note\"></textarea>\n      </div>\n    </div>\n\n    <div class=\"stack\" style=\"gap:12px\">\n      <div class=\"card stack\">\n        <b style=\"font-weight:500\">Customer</b>\n        <span>Customer name</span>\n        <small class=\"muted\">customer@example.com</small>\n        <small class=\"muted\">3 previous orders</small>\n      </div>\n      <div class=\"card stack\">\n        <b style=\"font-weight:500\">Shipping address</b>\n        <small class=\"muted\">Street address<br>City, State ZIP</small>\n      </div>\n      <div class=\"card stack\">\n        <b style=\"font-weight:500\">Payment</b>\n        <dl class=\"kv\" style=\"margin:0\"><dt>Method</dt><dd>Card</dd><dt>Status</dt><dd>Paid</dd></dl>\n      </div>\n    </div>\n  </div>\n</div>\n</canopy-markup>"
